CREATE TABLE menu_categories(id uuid PRIMARY KEY, name text NOT NULL UNIQUE, position integer NOT NULL DEFAULT 0);
CREATE TABLE menu_items(id uuid PRIMARY KEY, category_id uuid NOT NULL REFERENCES menu_categories(id), name text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', price_cents integer NOT NULL CHECK(price_cents BETWEEN 1 AND 1000000), sold_out boolean NOT NULL DEFAULT false, photo_key text);
CREATE TABLE menu_options(id uuid PRIMARY KEY, item_id uuid NOT NULL REFERENCES menu_items(id), name text NOT NULL, required boolean NOT NULL DEFAULT false, UNIQUE(item_id,name));
CREATE TABLE menu_choices(id uuid PRIMARY KEY, option_id uuid NOT NULL REFERENCES menu_options(id), name text NOT NULL, delta_cents integer NOT NULL CHECK(delta_cents BETWEEN -1000000 AND 1000000), UNIQUE(option_id,name));
CREATE TABLE opening_hours(day integer PRIMARY KEY CHECK(day BETWEEN 0 AND 6), opens time NOT NULL, closes time NOT NULL, closed boolean NOT NULL DEFAULT false, CHECK(opens < closes));
CREATE TABLE pickup_slots(id uuid PRIMARY KEY, starts_at timestamptz NOT NULL UNIQUE, capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 1000));
CREATE TABLE order_statuses(id uuid PRIMARY KEY, name text NOT NULL UNIQUE, position integer NOT NULL DEFAULT 0, is_ready boolean NOT NULL DEFAULT false);
CREATE TABLE orders(id uuid PRIMARY KEY, number bigint GENERATED ALWAYS AS IDENTITY UNIQUE, customer_id uuid REFERENCES app_users(id), email text NOT NULL, slot_id uuid NOT NULL REFERENCES pickup_slots(id), status_id uuid NOT NULL REFERENCES order_statuses(id), payment_state text NOT NULL DEFAULT 'pending' CHECK(payment_state IN ('pending','paid','failed')), total_cents integer NOT NULL CHECK(total_cents > 0), checkout_ref text UNIQUE, checkout_url text, checkout_key uuid NOT NULL UNIQUE, link_nonce text NOT NULL, link_expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz);
CREATE INDEX orders_slot ON orders(slot_id,payment_state);
CREATE INDEX orders_customer ON orders(customer_id,created_at);
CREATE TABLE order_lines(id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), item_id uuid NOT NULL REFERENCES menu_items(id), description text NOT NULL, quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 20), unit_cents integer NOT NULL CHECK(unit_cents > 0));
CREATE TABLE order_line_choices(line_id uuid NOT NULL REFERENCES order_lines(id), choice_id uuid NOT NULL REFERENCES menu_choices(id), PRIMARY KEY(line_id,choice_id));
CREATE TABLE order_mail(id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), kind text NOT NULL CHECK(kind IN ('confirmed','ready')), delivery text NOT NULL DEFAULT 'pending', UNIQUE(order_id,kind));
